from abc import abstractmethod, ABCMeta

from taf.ul.ettf.ta_matchers.matchers import MatchingError, MatchingResult
from taf.ul.ettf.logger import custom_logger


logger = custom_logger('NonOrderedMatcher')


class UnexpectedMessageError(Exception):
    pass


class PartialMatch(MatchingResult):
    def __init__(self):
        super(PartialMatch, self).__init__(mismatches=[])

    def __bool__(self):
        return False

    __nonzero__ = __bool__


class MatcherWraper(object):
    __metaclass__ = ABCMeta

    def __init__(self, matchers):
        self._matchers, self._negative_matchers = self._segragate_matchers(matchers)

    @staticmethod
    def _segragate_matchers(matchers):
        regular = []
        negative = []
        for reg, neg in matchers:
            if reg is not None:
                regular.append(reg)
            if neg is not None:
                negative.append(neg)
        return regular, negative

    @property
    def matchers(self):
        return self._matchers

    @property
    def negative_matchers(self):
        return self._negative_matchers

    def append_callback(self, callback):
        for m in self._matchers + self._negative_matchers:
            m.append_callback(callback)

    def __eq__(self, other):
        if not hasattr(other, 'matchers'):
            return False
        return self._matchers == other.matchers and self._negative_matchers == other.negative_matchers

    def match(self, packet):
        matching_result = self(packet)
        if not matching_result:
            raise MatchingError(matching_result.mismatches)

    @abstractmethod
    def __call__(self, packet):
        pass

    def _check_negative_matchers(self, packet):
        for matcher in self._negative_matchers:
            try:
                matcher.match(packet)
                self._packet_matched_negative(matcher)
            except MatchingError:
                pass

    @staticmethod
    def _packet_matched_negative(matcher):
        raise UnexpectedMessageError('{}'.format(matcher.get_name()))

    def _no_matchers_left(self):
        return not self._matchers

    def _no_negative_matchers_left(self):
        return not self._negative_matchers

    def no_all_matchers_left(self):
        return not self._matchers + self._negative_matchers
